-- 2차 묶음 1 적용 확인(읽기 전용). applied_rows와 backed_up_rows가 120이면 정상.
WITH r AS (SELECT * FROM jsonb_to_recordset($payload$[{"id": 2, "word": "가계순저축률", "beforeLength": 455, "after": "가계가 쓸 수 있는 돈 가운데 쓰지 않고 남긴 몫이 얼마나 되는지 보여주는 비율이에요. 처분가능소득에 무상교육 같은 정부의 현물 지원과 연금 납부·수령 차액을 더한 금액을 분모로 삼아 계산해요. 가계가 얼마나 아껴 쓰는지, 즉 저축 성향을 살필 때 가장 많이 쓰는 지표예요."}, {"id": 3, "word": "가계신용통계", "beforeLength": 216, "after": "가계가 진 빚이 모두 얼마인지 모아 보여주는 통계예요. 은행 같은 금융기관 대출뿐 아니라 카드 할부처럼 물건을 외상으로 산 판매신용까지 합쳐서 계산해요. 가계 빚이 얼마나 빨리 늘거나 줄어드는지 살필 때 가장 기본이 되는 자료예요."}, {"id": 4, "word": "가계처분가능소득", "beforeLength": 394, "after": "가계가 번 돈에서 세금 등을 빼고 소비나 저축에 자유롭게 쓸 수 있는 소득이에요. 1인당 국민총소득에는 기업과 정부 몫도 섞여 있어서 가계 살림과는 다르게 움직일 수 있어요. 그래서 가계가 실제로 느끼는 구매력을 보려면 이 소득을 따로 살펴봐요."}, {"id": 5, "word": "가교은행", "beforeLength": 420, "after": "문을 닫게 된 금융회사의 자산과 부채를 잠시 넘겨받아 운영하는 임시 은행이에요. 예금 지급 같은 업무를 이어가면서 그동안 인수할 곳을 찾거나 채권·채무 정리를 진행해요. 파산 충격을 줄이고 정리할 시간을 벌 수 있으며, 정리가 끝나면 함께 없어져요."}, {"id": 6, "word": "가산금리", "beforeLength": 589, "after": "기준이 되는 금리 위에 빌리는 사람의 신용도 등을 따져 덧붙이는 금리예요. 신용도가 높으면 적게, 낮으면 많이 붙어서 같은 대출이라도 사람마다 금리가 달라져요. 보통 bp라는 단위로 나타내는데, 1bp는 0.01%포인트예요."}, {"id": 7, "word": "가상자산", "beforeLength": 699, "after": "경제적 가치가 있고 전자적으로 사고팔거나 옮길 수 있는 디지털 증표를 말해요. 다만 전자화폐나 전자증권, 게임 아이템 같은 것은 법에서 따로 빼고 있어요. 투자나 결제에 쓰이기도 하지만 가격이 크게 출렁여 일반 금융자산보다 위험이 커요."}, {"id": 8, "word": "가상자산공개(ICO)", "beforeLength": 639, "after": "신생기업이 새 코인이나 토큰을 만들어 팔아서 사업 자금을 모으는 방식이에요. 투자자는 원화 같은 법정화폐나 비트코인을 내고 새로 발행된 토큰을 받아요. 주식을 주는 기업공개와 달리 회사 소유권이 아니라 프로젝트가 성공했을 때 가치가 오를 토큰을 얻어요."}, {"id": 9, "word": "간접금융", "beforeLength": 614, "after": "은행 같은 금융기관이 예금으로 모은 돈을 기업이나 가계에 빌려주며 중간에서 돈을 이어주는 방식이에요. 예금자는 은행을 믿고 맡기고, 대출의 위험은 은행이 스스로 떠안아요. 기업이 주식·채권을 직접 팔아 돈을 구하는 직접금융과 대비되는 개념이에요."}, {"id": 10, "word": "간접세", "beforeLength": 577, "after": "세금을 내는 사람과 실제로 부담하는 사람이 다른 세금이에요. 부가가치세는 가게가 납부하지만 그 금액은 물건값에 붙어 소비자가 부담해요. 걷기 쉽다는 장점이 있지만 소득과 상관없이 같은 세율이라 소득이 적은 사람에게 상대적으로 무거워요."}, {"id": 11, "word": "간편 송금", "beforeLength": 219, "after": "앱에서 비밀번호나 지문만으로 다른 사람에게 돈을 보내는 서비스예요. 예전처럼 공인인증서나 일회용 비밀번호를 거치지 않아도 되어 절차가 훨씬 짧아요. 토스, 카카오페이, 네이버페이 같은 서비스가 대표적인 예예요."}, {"id": 12, "word": "감독자협의회(Supervisory College)", "beforeLength": 239, "after": "여러 나라에서 영업하는 금융회사를 함께 감독하려고 각국 감독당국이 모인 협의체예요. 본점이 있는 나라와 지점·자회사가 있는 나라의 감독당국이 정보를 나누고 감독에 협력해요. 금융회사는 세계를 무대로 움직이는데 감독은 나라별로 나뉘는 한계를 메우려는 장치예요."}, {"id": 13, "word": "갑기금(Capital A)", "beforeLength": 300, "after": "외국은행의 국내지점이 장부에 자본금으로 잡아 두는 원화 자금이에요. 본점이 외화를 팔아 원화로 바꿔 지점에 보내 주거나 지점이 쌓아 둔 이익에서 옮겨 마련해요. 국내 법인이 아닌 지점에도 손실을 버틸 밑천이 필요해서 법으로 최소 금액을 정해 두고 있어요."}, {"id": 14, "word": "거래정보저장소", "beforeLength": 449, "after": "거래소를 거치지 않고 당사자끼리 맺는 장외파생상품 거래 내역을 한곳에 모아 관리하는 기관이에요. 거래 당사자는 계약 내용을 이곳에 보고하고, 감독당국은 모인 자료로 위험이 쌓이는지 살펴요. 2008년 금융위기 때 장외거래가 불투명해 위기가 커진 경험에서 도입이 추진됐어요."}, {"id": 15, "word": "거시건전성 정책", "beforeLength": 421, "after": "개별 금융회사가 아니라 금융시스템 전체가 흔들리지 않도록 위기를 미리 막는 정책이에요. 대출이 한꺼번에 과하게 늘거나 금융회사끼리 위험이 얽혀 퍼지는 것을 억제하는 방식으로 작동해요. 회사 하나하나의 건전성을 보는 미시건전성 정책과 짝을 이루는 개념이에요."}, {"id": 16, "word": "거액익스포저 규제", "beforeLength": 605, "after": "은행이 한 거래상대방이나 서로 연결된 기업 집단에 돈을 지나치게 몰아 빌려주지 못하게 막는 규제예요. 대출·보증 등을 합친 위험 노출액이 은행 기본자본의 25%를 넘지 못하게 해요. 상대방 하나가 무너져도 은행까지 함께 흔들리지 않게 하려는 장치예요."}, {"id": 17, "word": "거액지급시스템", "beforeLength": 381, "after": "금융기관끼리 큰돈을 주고받을 때 쓰는 자금이체 시스템이에요. 콜거래나 증권·외환 매매 대금처럼 한 건 금액이 큰 이체를 처리하며, 보통 건별로 즉시 결제해 위험을 줄여요. 대부분 중앙은행이 직접 운영하며, 우리나라의 한은금융망이 대표적이에요."}, {"id": 18, "word": "결제리스크", "beforeLength": 537, "after": "예상하지 못한 사정으로 결제가 제때 이뤄지지 않거나 그로 인해 손실이 생길 위험이에요. 거래 약속 시점과 실제 돈이 오가는 시점 사이의 시차, 참가기관의 재무 상태 등이 원인이 돼요. 자주 일어나지는 않아도 한번 터지면 손실이 커서 꼼꼼히 관리해야 해요."}, {"id": 19, "word": "결제부족자금 공동분담제", "beforeLength": 539, "after": "결제 시스템의 한 참가기관이 돈을 못 내면 나머지 기관들이 부족분을 나눠 메우는 제도예요. 분담 비율은 기관 규모나 그 기관에 열어 준 신용한도 등을 기준으로 정해요. 한 곳의 불이행이 연쇄 부도로 번지는 것을 막고, 참가기관이 거래 상대를 더 신중히 고르게 만들어요."}, {"id": 20, "word": "결제완결성", "beforeLength": 535, "after": "한번 끝난 결제는 어떤 사정이 생겨도 취소되거나 무효가 되지 않는다는 원칙이에요. 예를 들어 결제를 마친 뒤 참가기관이 파산하더라도 이미 이뤄진 지급은 되돌릴 수 없어요. 이것이 보장되지 않으면 끝난 거래가 뒤집혀 금융시스템 전체가 혼란에 빠질 수 있어요."}, {"id": 21, "word": "겸업주의", "beforeLength": 824, "after": "한 금융회사가 은행·증권·보험 업무를 함께 할 수 있게 하는 방식이에요. 한 회사 안에서 모두 하는 내부겸업과 금융지주 아래 자회사로 나눠 하는 외부겸업이 있어요. 회사마다 한 업종만 맡게 하는 전업주의와 대비되며, 우리나라는 금융지주회사 제도로 외부겸업을 도입했어요."}, {"id": 22, "word": "경기", "beforeLength": 700, "after": "생산·소비·투자 같은 나라 전체의 경제활동이 얼마나 활발한지를 가리키는 말이에요. 경기는 호황, 후퇴, 불황, 회복을 번갈아 거치며 오르내리는데 이를 경기순환이라고 해요. 여러 경제지표나 기업·소비자 설문을 보고 지금 경기가 어디쯤인지 판단해요."}, {"id": 23, "word": "경기순응성", "beforeLength": 329, "after": "금융 활동이 경기 흐름과 같은 방향으로 움직여 오르내림을 더 키우는 성질이에요. 호황에는 은행이 대출 심사를 느슨하게 해 돈이 더 풀리고, 불황에는 심사를 조여 대출이 크게 줄어요. 그래서 정책당국은 이런 쏠림을 누그러뜨리는 경기대응적 수단을 마련하려고 해요."}, {"id": 24, "word": "경기조절정책(경제안정화정책)", "beforeLength": 467, "after": "경기가 지나치게 달아오르거나 식었을 때 정상 수준으로 되돌리려는 정부와 중앙은행의 조치예요. 불황이면 정부는 지출을 늘리거나 세금을 줄이고, 중앙은행은 금리를 내리거나 통화량을 늘려요. 반대로 과열이면 지출을 줄이고 금리를 올려 경제 전체의 수요를 눌러요."}, {"id": 25, "word": "경기종합지수", "beforeLength": 503, "after": "여러 경제지표를 하나로 합쳐 경기 흐름을 한눈에 보여주는 지수예요. 생산, 소비 같은 지표에서 계절 요인을 걷어내고 크기를 맞춘 뒤 더해서 만들어요. 앞날을 보는 선행지수, 현재를 보는 동행지수, 사후 확인용 후행지수로 나눠 써요."}, {"id": 27, "word": "경영실태평가", "beforeLength": 638, "after": "감독당국이 금융회사의 경영 상태를 점검해 1등급부터 5등급까지 매기는 제도예요. 자본 적정성, 자산 건전성, 경영진 능력, 수익성, 유동성 등을 항목별로 따져 종합 등급을 정해요. 등급이 나쁘면 경영 개선을 요구하는 조치로 이어져 부실을 일찍 막는 데 쓰여요."}, {"id": 28, "word": "경제 서프라이즈 지수", "beforeLength": 468, "after": "발표된 경제지표가 시장 예상보다 좋았는지 나빴는지를 수치로 보여주는 지수예요. 고용, 물가 같은 지표의 실제 값과 전문가 예상치의 차이를 모아 계산하며, 양수면 예상보다 좋다는 뜻이에요. 투자심리에 영향이 커서 주식시장 흐름을 살필 때 자주 참고해요."}, {"id": 29, "word": "경제성장률", "beforeLength": 348, "after": "한 나라의 경제 규모가 일정 기간 동안 얼마나 커졌는지를 백분율로 나타낸 값이에요. 보통 물가 변동을 뺀 실질 국내총생산이 지난해나 지난 분기보다 몇 % 늘었는지로 계산해요. 경제가 얼마나 활발한지 보여주는 가장 대표적인 지표예요."}, {"id": 30, "word": "경제심리지수", "beforeLength": 521, "after": "기업과 소비자가 경제를 어떻게 느끼는지 합쳐서 하나로 나타낸 지수예요. 한국은행이 기업 설문과 소비자 설문에서 경기와 관련 깊은 항목을 골라 합성해 만들어요. 100보다 크면 민간의 심리가 과거 평균보다 낙관적이고, 작으면 비관적이라는 뜻이에요."}, {"id": 31, "word": "경제전망보고서", "beforeLength": 547, "after": "앞으로 성장률, 물가, 고용, 환율, 경상수지 등이 어떻게 될지 분석해 내놓는 보고서예요. 국내외 경제지표와 세계 경제 흐름을 바탕으로 예상치를 내고 근거를 설명해요. 가계·기업·정부가 소비, 투자, 예산 같은 계획을 세울 때 판단 기준으로 써요."}, {"id": 32, "word": "경제협력개발기구(OECD)", "beforeLength": 739, "after": "회원국들이 경제성장과 금융안정, 세계무역 확대를 위해 함께 일하는 국제기구예요. 각국의 정책 경험을 나누고 무역·조세·통계 등 여러 분야에서 공통 기준과 권고를 만들어요. 1961년에 설립됐고 우리나라는 1996년에 가입했어요."}, {"id": 33, "word": "경제활동인구", "beforeLength": 591, "after": "15세 이상 인구 가운데 일하고 있거나 일자리를 적극적으로 찾고 있는 사람을 말해요. 일하는 취업자와, 구직 중이며 바로 일할 수 있는 실업자를 합해서 계산해요. 학생이나 전업주부처럼 일도 구직도 하지 않는 사람은 비경제활동인구로 따로 분류해요."}, {"id": 34, "word": "경제후생지표", "beforeLength": 381, "after": "국민총소득만으로는 알기 어려운 삶의 질을 재려고 만든 지표예요. 국민총소득에 여가나 가사노동 같은 좋은 요소를 더하고, 공해 같은 나쁜 요소는 빼서 계산해요. 경제학자 노드하우스와 토빈이 제안했지만 이런 요소를 숫자로 바꾸기 어려워 널리 쓰이지는 않아요."}, {"id": 35, "word": "경직적 물가지수", "beforeLength": 332, "after": "가격이 잘 바뀌지 않는 품목만 모아 따로 만든 물가지수예요. 전기·수도 요금, 공공서비스, 담배처럼 정부 영향을 받거나 값이 쉽게 오르내리지 않는 품목이 주로 들어가요. 일시적 등락이 적어 물가의 장기 흐름을 가늠하는 데 유용해요."}, {"id": 36, "word": "계절변동조정시계열", "beforeLength": 507, "after": "명절이나 날씨처럼 해마다 같은 때 되풀이되는 영향을 걷어낸 통계 자료예요. 예를 들어 설 연휴가 낀 달은 생산이 줄어드는데, 이런 계절 요인을 통계 기법으로 제거해요. 이렇게 해야 지난달이나 지난 분기와 비교할 때 왜곡 없이 실제 변화를 볼 수 있어요."}, {"id": 37, "word": "계좌대체", "beforeLength": 289, "after": "증권을 사고팔 때 종이 증권을 직접 주고받지 않고 장부상 계좌끼리 옮겨 처리하는 방식이에요. 매도자와 매수자가 모두 계좌를 둔 중앙예탁기관에서 매도자 계좌의 증권을 매수자 계좌로 옮겨요. 거래가 많아 실물을 주고받기 어려워서, 우리나라는 한국예탁결제원이 이 방식으로 처리해요."}, {"id": 38, "word": "고객확인절차(KYC)", "beforeLength": 113, "after": "금융회사가 고객이 누구인지 확인하고 기록하는 절차예요. 계좌를 만들거나 큰돈을 거래할 때 신분증 등으로 신원을 확인하고 거래 목적을 묻기도 해요. 자금세탁이나 테러자금 같은 불법 거래를 막기 위해 법으로 정한 의무예요."}, {"id": 39, "word": "고용률", "beforeLength": 493, "after": "15세 이상 인구 가운데 취업자가 차지하는 비율이에요. 구직을 포기한 사람이 늘면 실업자에서 빠져 실업률은 오히려 낮아지지만 고용률은 그런 영향을 덜 받아요. 그래서 체감 고용 사정을 보려면 실업률과 함께 고용률을 살펴요."}, {"id": 40, "word": "고용보조지표", "beforeLength": 802, "after": "공식 실업률에 잡히지 않는 숨은 실업까지 넓게 보여주는 보조 지표예요. 더 일하고 싶은 단시간 근로자, 일할 뜻은 있지만 당장 구직하지 않은 사람 등을 함께 포함해요. 공식 실업률보다 높게 나오는 편이라 체감 고용 사정을 파악하는 데 도움이 돼요."}, {"id": 41, "word": "고정금리", "beforeLength": 650, "after": "처음 약정한 이자율이 만기까지 그대로 유지되는 금리예요. 시장금리가 오르든 내리든 내는 이자가 바뀌지 않아 상환 계획을 세우기 쉬워요. 금리 상승이 예상되면 유리하지만, 보통 같은 만기의 변동금리보다 조금 높게 정해져요."}, {"id": 42, "word": "고정금리부채권(SB)", "beforeLength": 515, "after": "정해진 날마다 미리 정한 이자를 주고 만기에 원금을 돌려주는 가장 기본적인 채권이에요. 주식으로 바꿀 권리 같은 특별한 조건이 없어서 국채·회사채 대부분이 이 형태로 발행돼요. 시장금리에 따라 이자가 바뀌는 변동금리부채권과 달리 받는 이자가 처음부터 끝까지 같아요."}, {"id": 43, "word": "고정이하여신비율", "beforeLength": 554, "after": "은행이 빌려준 돈 가운데 돌려받기 어려워진 부실 대출이 차지하는 비율이에요. 은행은 대출을 정상, 요주의, 고정, 회수의문, 추정손실 5단계로 나누는데 이 중 아래 세 단계를 합해 계산해요. 비율이 높을수록 은행 자산이 부실하다는 뜻이라 건전성을 볼 때 핵심 지표로 써요."}, {"id": 44, "word": "고정자본소모", "beforeLength": 613, "after": "공장이나 기계 같은 설비가 생산에 쓰이면서 닳아 줄어든 가치를 말해요. 예를 들어 자동차를 만드는 조립 기계는 쓸수록 낡는데, 그만큼의 가치 감소를 비용처럼 계산해요. 총생산에서 이 값을 빼야 한 해 동안 새로 만든 순수한 가치를 알 수 있어요."}, {"id": 45, "word": "고정환율제도", "beforeLength": 711, "after": "정부나 중앙은행이 환율을 정해진 수준에 묶어 두는 제도예요. 환율이 정한 선에서 벗어나려 하면 중앙은행이 외환을 사고팔아 수준을 지켜요. 환율 변동 충격은 줄일 수 있지만, 시장 수급에 맡기는 변동환율제도와 달리 자본 이동을 제한해야 하는 부담이 있어요."}, {"id": 46, "word": "고통지수", "beforeLength": 462, "after": "물가상승률과 실업률을 더해 국민이 느끼는 경제적 고통을 숫자로 나타낸 지수예요. 예를 들어 물가가 3% 오르고 실업률이 4%라면 지수는 7이 돼요. 미국 경제학자 오쿤이 고안했지만 나라마다 통계 기준이 달라 단순 비교는 조심해야 해요."}, {"id": 47, "word": "골디락스경제", "beforeLength": 410, "after": "경기가 지나치게 뜨겁지도 차갑지도 않아 물가와 고용이 안정된 채 성장하는 경제를 말해요. 동화 속 소녀가 너무 뜨겁지도 차갑지도 않은 수프를 고른 이야기에서 이름이 나왔어요. 인플레이션과 실업 걱정이 모두 적은 이상적인 상태를 가리킬 때 써요."}, {"id": 48, "word": "공개시장운영", "beforeLength": 572, "after": "중앙은행이 금융시장에서 채권 같은 증권을 사고팔아 시중의 돈 양과 금리를 조절하는 수단이에요. 증권을 사들이면 돈이 시중에 풀리고, 팔면 돈이 중앙은행으로 거둬들여져요. 시기와 규모를 유연하게 정할 수 있어 대부분의 중앙은행이 주된 통화정책 수단으로 써요."}, {"id": 49, "word": "공공재", "beforeLength": 342, "after": "국방, 도로, 공원처럼 여러 사람이 함께 쓰는 재화나 서비스를 말해요. 한 사람이 써도 다른 사람의 몫이 줄지 않고, 돈을 안 낸 사람만 골라 못 쓰게 하기도 어려워요. 그래서 시장에 맡기면 충분히 공급되지 않아 주로 정부가 세금으로 제공해요."}, {"id": 50, "word": "공급병목", "beforeLength": 414, "after": "물건이 만들어져 소비자에게 가는 과정 중 한 단계가 막혀 전체 흐름이 늦어지는 현상이에요. 예를 들어 반도체가 부족하면 다른 부품이 다 있어도 자동차를 완성하지 못해요. 공급이 달리면 관련 물건값이 오르고 배송이 늦어져 물가와 생산 모두에 부담이 돼요."}, {"id": 52, "word": "공급탄력성", "beforeLength": 453, "after": "가격이 변할 때 공급량이 얼마나 민감하게 반응하는지 나타내는 값이에요. 공급량 변화율을 가격 변화율로 나눠 구하며, 1보다 크면 탄력적, 작으면 비탄력적이라고 해요. 농산물처럼 생산에 시간이 걸리는 상품은 가격이 올라도 공급을 바로 늘리기 어려워 이 값이 낮아요."}, {"id": 53, "word": "공동부유", "beforeLength": 344, "after": "소수만 부유해지는 것이 아니라 국민 모두가 함께 잘살자는 중국의 정책 방향이에요. 독과점 기업 규제, 기업 기부 독려, 부동산세 추진 등으로 부의 쏠림을 줄이려 해요. 빠른 성장 뒤 커진 불평등이 사회 안정을 위협한다는 판단에서 시진핑 주석이 강조했어요."}, {"id": 54, "word": "관리통화제도", "beforeLength": 364, "after": "금 보유량과 상관없이 중앙은행이 경제 상황에 맞춰 통화량을 조절하는 제도예요. 기준금리 조정이나 공개시장운영 같은 수단으로 물가를 안정시키고 경기를 조절해요. 금을 가진 만큼만 돈을 찍던 금본위제도와 대비되며, 지금 대부분의 나라가 이 방식을 써요."}, {"id": 55, "word": "광의통화(M2)", "beforeLength": 393, "after": "현금과 바로 꺼내 쓸 수 있는 예금에 만기 2년 이내 정기예금 같은 상품까지 더한 통화량이에요. 약간의 이자 손해만 감수하면 금방 현금으로 바꿀 수 있는 상품까지 넓게 포함해요. 시중에 돈이 얼마나 풀렸는지 볼 때 가장 많이 쓰는 지표이고, 늘어나면 물가 상승 압력이 될 수 있어요."}, {"id": 56, "word": "교환사채(EB)", "beforeLength": 596, "after": "회사채를 가진 사람이 원하면 발행회사가 보유한 다른 회사 주식으로 바꿔 받을 수 있는 채권이에요. 주가가 오르면 주식으로 교환해 차익을 얻고, 그렇지 않으면 채권으로 이자와 원금을 받아요. 발행회사의 새 주식으로 바꾸는 전환사채와 달리 이미 가진 다른 회사 주식을 내준다는 점이 달라요."}, {"id": 57, "word": "교환성 통화", "beforeLength": 385, "after": "외환시장에서 다른 통화, 특히 미국 달러와 자유롭게 바꿀 수 있는 통화를 말해요. 국제통화기금 협정은 회원국이 경상거래에서 자기 나라 통화를 자유롭게 바꿀 수 있게 하도록 정하고 있어요. 좁게는 달러, 유로, 엔, 파운드, 위안처럼 국제 거래에 널리 쓰이는 통화를 가리켜요."}, {"id": 58, "word": "구독경제", "beforeLength": 353, "after": "제품이나 서비스를 사서 소유하는 대신 정기적으로 돈을 내고 이용하는 방식이에요. 동영상 스트리밍처럼 매달 요금을 내면 그 기간 동안 쓸 수 있는 권리를 얻어요. 처음 부담이 적은 대신 쌓이면 비용이 커지고 해지를 깜빡하면 불필요한 지출이 생길 수 있어요."}, {"id": 59, "word": "구매력평가 환율", "beforeLength": 429, "after": "두 나라에서 같은 물건을 같은 값에 살 수 있도록 맞춘 이론상의 환율이에요. 예를 들어 같은 커피가 한국에서 5천 원, 미국에서 5달러라면 1달러는 1천 원이 되어야 한다고 봐요. 나라별 물가 차이를 고려해 소득이나 생활 수준을 비교할 때 써요."}, {"id": 60, "word": "구인배수", "beforeLength": 285, "after": "일자리 수를 취업을 원하는 사람 수로 나눈 값이에요. 예를 들어 0.7이면 구직자 열 명당 일자리가 일곱 개 있다는 뜻이에요. 1보다 크면 일자리가 남고 작으면 부족하다는 의미라 고용 사정을 가늠하는 데 써요."}, {"id": 61, "word": "국가경쟁력", "beforeLength": 332, "after": "한 나라가 성장을 이어가고 국민 삶의 질을 높일 수 있는 능력을 말해요. 대표적으로 스위스 국제경영개발원이 통계와 기업인 설문을 합쳐 해마다 나라별 순위를 발표해요. 경제 성과, 정부 효율성, 기업 효율성, 인프라 같은 분야를 따져 순위를 매겨요."}, {"id": 62, "word": "국가신용등급", "beforeLength": 590, "after": "한 나라가 빚을 제때 갚을 능력과 의지가 얼마나 되는지 평가해 매긴 등급이에요. S&P, 무디스, 피치 같은 국제신용평가사가 경제 성장, 나랏빚, 정치 안정성 등을 따져 정해요. 등급이 높을수록 해외에서 낮은 금리로 돈을 빌릴 수 있어 그 나라 정부와 기업 모두에 영향을 줘요."}, {"id": 63, "word": "국가채무", "beforeLength": 337, "after": "정부가 재정적자를 메우려고 국내외에서 빌린 돈, 즉 나라의 빚이에요. 한번 쌓이면 새 적자가 없어도 이자 부담 때문에 빚이 계속 불어나는 성질이 있어요. 그래서 보통 국내총생산 대비 비율로 규모를 살피며 재정이 감당할 수 있는지 관리해요."}, {"id": 64, "word": "국고금 실시간 전자이체", "beforeLength": 363, "after": "정부가 지급할 돈을 수표 대신 받는 사람의 은행 계좌로 곧바로 넣어 주는 방식이에요. 정부 재정시스템과 한국은행, 금융기관 전산망을 연결해 2003년부터 시행됐어요. 받는 사람은 수표를 받아 다시 입금하는 수고를 덜고, 정부는 수표 발행 비용을 줄였어요."}, {"id": 65, "word": "국고대리점", "beforeLength": 470, "after": "한국은행을 대신해 세금 같은 나랏돈을 받아 주도록 지정된 금융기관 영업점이에요. 나랏돈 출납은 원래 한국은행 일이지만 지점이 적어 은행 영업점과 계약해 수납을 맡겨요. 덕분에 국민은 가까운 은행에서 세금이나 공과금을 낼 수 있어요."}, {"id": 66, "word": "국고수표", "beforeLength": 201, "after": "정부가 나랏돈을 지급할 때 쓰던 수표예요. 2003년부터 계좌로 바로 입금하는 전자이체 방식으로 바뀌면서 평소에는 쓰지 않아요. 다만 금융기관 전산 장애 같은 비상 상황에 대비해 제도는 없애지 않고 남겨 두었어요."}, {"id": 67, "word": "국고전산망", "beforeLength": 402, "after": "정부, 한국은행, 금융기관의 전산시스템을 연결해 나랏돈 업무를 전자적으로 처리하는 망이에요. 이 망을 통해 정부 지급금을 실시간으로 계좌에 넣고, 세금 수납 자료 같은 파일을 주고받아요. 한국은행이 2003년에 구축했으며 종이 수표와 서류 처리를 크게 줄였어요."}, {"id": 68, "word": "국내공급물가지수", "beforeLength": 213, "after": "국내에서 만든 물건값과 수입한 물건값을 합쳐 국내 시장에 공급되는 상품·서비스의 가격 수준을 보여주는 지수예요. 원재료, 중간재, 최종재로 단계를 나눠 계산해요. 그래서 원자재 가격 상승이 완제품 가격으로 어떻게 번지는지 따라가 보기에 좋아요."}, {"id": 69, "word": "국내총생산(GDP)", "beforeLength": 305, "after": "한 나라 안에서 일정 기간 새로 만들어 낸 부가가치를 모두 더한 값이에요. 국적과 관계없이 국내에서 일어난 생산이면 외국인이 만든 것도 포함해요. 물가 변동을 뺀 실질 기준은 경제성장률을 계산할 때, 명목 기준은 경제 규모를 볼 때 주로 써요."}, {"id": 70, "word": "국내총투자율", "beforeLength": 259, "after": "나라 전체가 쓸 수 있는 소득 가운데 공장·설비·재고 같은 투자에 쓰인 몫의 비율이에요. 공장이나 기계 같은 고정투자와 쌓아 둔 재고의 변화를 합친 총투자를 국민총처분가능소득으로 나눠 구해요. 미래 생산능력을 키우는 데 소득을 얼마나 쓰는지 보여줘요."}, {"id": 71, "word": "국민계정체계(SNA)", "beforeLength": 523, "after": "나라 경제의 생산, 소득, 지출, 자산의 흐름을 기업 회계처럼 기록하는 국제 공통 기준이에요. 국민소득, 산업연관표, 자금순환표, 국제수지표처럼 따로 만들던 통계를 하나의 틀로 묶어요. 유엔 등이 기준을 정하므로 여러 나라의 경제 통계를 같은 잣대로 비교할 수 있어요."}, {"id": 72, "word": "국민대차대조표", "beforeLength": 809, "after": "특정 시점에 나라 전체와 가계·기업·정부 등이 가진 자산과 부채를 정리한 표예요. 토지·건물 같은 실물자산과 금융자산에서 부채를 빼면 순자산이 나오며, 나라 전체 순자산을 국부라고 해요. 한 해의 흐름이 아니라 쌓인 재산 상태를 보여준다는 점에서 국민소득 통계와 달라요."}, {"id": 73, "word": "국민부담률", "beforeLength": 546, "after": "국민이 내는 세금과 사회보험료를 합쳐 국내총생산 대비 비율로 나타낸 값이에요. 세금만 보는 조세부담률에 국민연금·건강보험료 같은 사회보장기여금 비율을 더해 계산해요. 강제로 내는 돈 전체를 보여주므로 나라별 국민 부담을 비교할 때 많이 써요."}, {"id": 74, "word": "국민소득", "beforeLength": 299, "after": "한 나라 국민이 노동, 자본, 경영을 제공한 대가로 벌어들인 순수한 소득의 합계예요. 일한 대가인 임금과 기업 이윤 같은 영업잉여를 더해서 구해요. 국민총소득에서 설비가 닳은 몫과 세금 성격의 항목을 빼서 계산하므로 실제로 나눠 가진 소득에 가까워요."}, {"id": 75, "word": "국민연금", "beforeLength": 442, "after": "일하는 동안 소득의 일부를 보험료로 내고 나중에 연금으로 돌려받는 공적 사회보험이에요. 나이가 들어 받는 노령연금 외에 장애가 생기면 장애연금, 가입자가 사망하면 유족연금도 지급해요. 퇴직연금, 개인연금과 함께 노후 소득을 받치는 기본 장치예요."}, {"id": 77, "word": "국민총소득(GNI)", "beforeLength": 596, "after": "한 나라 국민이 국내외에서 일정 기간 벌어들인 임금, 이자, 배당 같은 소득을 모두 합친 값이에요. 국내총생산에 국민이 해외에서 번 소득을 더하고 외국인이 국내에서 번 소득은 빼서 구해요. 국민이 실제 얻은 소득을 보여주므로 1인당 기준으로 생활 수준을 비교할 때 써요."}, {"id": 78, "word": "국부펀드", "beforeLength": 703, "after": "정부가 가진 자금을 국내외 주식, 채권 등에 투자해 수익을 내도록 굴리는 국가 소유 투자기금이에요. 원유 같은 원자재 수출로 번 돈이나 외환보유액, 재정 잉여금 등을 재원으로 삼아요. 연기금이나 사모펀드와 운용 방식은 비슷하지만 주인이 민간이 아닌 국가라는 점이 달라요."}, {"id": 79, "word": "국외투자율", "beforeLength": 773, "after": "나라 전체가 쓸 수 있는 소득 가운데 국내 투자에 쓰고도 남아 해외로 나간 저축의 비율이에요. 총저축에서 국내투자를 빼고, 이를 국민총처분가능소득으로 나눠 구해요. 값이 양수면 저축이 국내 투자보다 많아 남는 돈이 해외 자산으로 흘러갔다는 뜻이에요."}, {"id": 80, "word": "국제결제은행(BIS)", "beforeLength": 500, "after": "각국 중앙은행들이 정책 협력을 위해 모인 국제금융기구로, 1930년에 세워져 가장 오래됐어요. 중앙은행 총재 회의를 정기적으로 열어 정보를 나누고, 중앙은행의 국제 결제 업무도 지원해요. 은행 자기자본 규제 같은 국제 금융기준 논의를 뒷받침하는 곳으로도 잘 알려져 있어요."}, {"id": 81, "word": "국제금융시장", "beforeLength": 352, "after": "국경을 넘어 돈을 빌리고 빌려주는 거래가 이뤄지는 시장이에요. 런던, 뉴욕 같은 금융 중심지라는 장소를 뜻하기도 하고, 나라 사이 자금 거래 전체를 가리키기도 해요. 외환, 단기자금, 채권, 주식, 파생상품 시장 등을 모두 포함하는 넓은 개념이에요."}, {"id": 82, "word": "국제금융중심지", "beforeLength": 433, "after": "세계적인 금융회사가 모여 국제 금융거래가 대규모로 꾸준히 일어나는 도시나 지역이에요. 통화의 국제적 신뢰, 탄탄한 경제력, 발달한 금융시장, 빠른 정보 흐름 같은 조건을 갖춰야 해요. 뉴욕, 런던, 도쿄가 대표적이에요."}, {"id": 83, "word": "국제산업연관표", "beforeLength": 537, "after": "산업끼리 원료와 제품을 주고받은 관계를 정리한 산업연관표를 여러 나라에 걸쳐 수출입으로 이어 하나로 만든 표예요. 한 나라 산업이 다른 나라 산업과 어떻게 연결되는지까지 보여줘요. 글로벌 공급망이나 나라 간 경제적 의존 관계를 분석할 때 주로 써요."}, {"id": 84, "word": "국제수지(BOP)", "beforeLength": 493, "after": "일정 기간 한 나라와 외국 사이에 오간 상품·서비스·소득·자본·금융 거래의 돈을 모두 정리한 것이에요. 크게 경상수지, 자본수지, 금융계정으로 나뉘며 상품을 사고판 결과는 경상수지에 담겨요. 외국과의 거래로 돈을 얼마나 벌고 썼는지, 해외 투자는 얼마나 했는지 한눈에 볼 수 있어요."}, {"id": 85, "word": "국제수지표", "beforeLength": 383, "after": "한 나라 거주자와 외국 거주자 사이의 모든 경제 거래를 국제 기준에 맞춰 기록한 표예요. 국적이 아니라 경제활동의 중심이 어디에 있느냐로 거주자를 나누고, 대가 없는 원조나 송금도 포함해요. 특정 시점의 잔액이 아니라 일정 기간 동안 일어난 거래를 모은 통계라는 점이 특징이에요."}, {"id": 86, "word": "국제원유가격", "beforeLength": 590, "after": "국제 시장에서 거래되는 대표 원유의 가격을 말해요. 미국 서부텍사스유는 북미, 브렌트유는 유럽, 두바이유는 중동 지역의 기준 가격 역할을 해요. 우리나라는 중동산 원유를 많이 들여오기 때문에 주로 두바이유 가격을 눈여겨봐요."}, {"id": 87, "word": "국제증권감독기구(IOSCO)", "beforeLength": 455, "after": "세계 각국의 증권 감독기관이 모여 증권시장 규제의 공통 기준을 만드는 국제기구예요. 투자자 보호, 시장의 공정성과 투명성 확보 같은 원칙을 정하고 회원 기관이 이를 따르도록 해요. 1983년에 출범했으며, 은행 분야의 바젤위원회처럼 증권 분야의 기준을 이끄는 역할을 해요."}, {"id": 88, "word": "국제통화기금(IMF)", "beforeLength": 616, "after": "국제통화와 금융제도의 안정을 위해 1945년에 세워진 국제금융기구예요. 회원국의 환율·외환 정책을 점검하고, 외환위기에 빠진 나라에는 자금을 빌려주며 경제 개혁을 요구하기도 해요. 우리나라도 1997년 외환위기 때 이 기구의 구제금융을 받은 경험이 있어요."}, {"id": 89, "word": "국제통화시장(IMM)", "beforeLength": 454, "after": "1972년 미국 시카고상업거래소 안에 세워진 세계 최초의 통화선물 거래소예요. 달러, 유로, 엔 같은 주요 통화를 미래의 정해진 날 정한 가격에 사고파는 표준화된 계약이 거래돼요. 투자자들의 매수·매도 포지션 자료는 환율 전망을 읽는 참고 지표로 쓰여요."}, {"id": 90, "word": "국제투자대조표(IIP)", "beforeLength": 404, "after": "특정 시점에 한 나라가 외국에 가진 금융자산과 외국에 진 금융부채의 잔액을 정리한 표예요. 국제수지가 일정 기간의 거래 흐름이라면, 이 표는 그 결과 쌓인 잔액을 보여줘요. 환율이나 주가 변화로 가치가 달라진 부분까지 반영해 나라의 대외 재무 상태를 판단하는 데 써요."}, {"id": 91, "word": "국제회계기준", "beforeLength": 670, "after": "나라마다 다른 회계 처리 방식을 하나로 맞추려고 국제회계기준위원회가 만든 공통 회계 기준이에요. 자산을 공정가치, 즉 현재 시장가치로 평가하는 것을 중시하고 자회사까지 합친 연결재무제표 중심으로 보고해요. 같은 기준으로 쓰니 투자자가 여러 나라 기업의 재무제표를 쉽게 비교할 수 있어요."}, {"id": 92, "word": "국채", "beforeLength": 732, "after": "정부가 나랏일에 필요한 돈을 마련하려고 발행하는 채권이에요. 대부분은 국고채로, 2년부터 50년까지 다양한 만기로 경쟁입찰을 거쳐 발행돼요. 정부가 갚기 때문에 떼일 위험이 매우 낮아 다른 채권 금리의 기준이 되기도 해요."}, {"id": 93, "word": "국채선물", "beforeLength": 599, "after": "국채를 미래의 정해진 날 지금 정한 가격으로 사고팔기로 약속하는 거래예요. 금리가 오르면 채권값이 떨어지므로 국채를 가진 투자자는 선물을 미리 팔아 손실을 줄일 수 있어요. 우리나라는 1999년 3년 만기 상품을 시작으로 한국거래소에서 여러 만기 상품이 거래돼요."}, {"id": 94, "word": "규모의 경제", "beforeLength": 386, "after": "생산량이 늘수록 제품 하나를 만드는 데 드는 평균 비용이 낮아지는 현상이에요. 공장이나 연구개발에 큰돈이 처음 들지만, 많이 만들수록 그 비용이 여러 제품에 나눠지기 때문이에요. 반도체, 자동차, 철강처럼 초기 투자가 큰 산업에서 큰 기업이 유리한 이유가 돼요."}, {"id": 95, "word": "규제 샌드박스", "beforeLength": 609, "after": "새로운 제품이나 서비스를 일정 기간 시험해 볼 수 있도록 기존 규제를 면제하거나 완화해 주는 제도예요. 소비자 보호 장치는 두되, 기업이 규제에 막히지 않고 실제 시장에서 검증해 보게 해요. 아이들이 안전하게 노는 모래놀이터에서 이름을 따왔으며, 영국이 핀테크에 먼저 도입했어요."}, {"id": 96, "word": "그램-리치-블라일리법", "beforeLength": 701, "after": "1999년 미국이 은행, 증권, 보험 업무를 한 금융그룹 안에서 함께 할 수 있도록 허용한 법이에요. 1933년 글래스-스티걸법이 막았던 상업은행의 증권 자회사 보유 금지 등 핵심 조항을 없앴어요. 이후 대형 금융그룹이 늘었고, 2008년 금융위기 뒤 겸업의 부작용 논란이 일었어요."}, {"id": 97, "word": "그린본드", "beforeLength": 568, "after": "조달한 돈을 재생에너지나 오염 저감 같은 기후·환경 사업에만 쓰기로 약속하고 발행하는 채권이에요. 발행자는 국제 원칙에 맞춰 돈을 어디에 썼는지 투자자에게 공개해요. 초기에는 세계은행 같은 국제기구가 주로 발행했지만 지금은 정부와 기업으로 넓어졌어요."}, {"id": 98, "word": "그림자금융(NBFI)", "beforeLength": 559, "after": "은행이 아니면서 돈을 모아 빌려주는 일을 하는 기관이나 활동을 말해요. 펀드, 환매조건부채권 거래, 대출을 증권으로 바꾸는 유동화기구 등이 대표적이며 은행만큼 엄격한 규제를 받지 않아요. 자금 공급을 늘리는 장점이 있지만 금융위기 때 위험을 키운 원인으로 지목되어 감시가 강화됐어요."}, {"id": 99, "word": "근원인플레이션율", "beforeLength": 357, "after": "농산물이나 석유처럼 날씨나 국제 정세로 값이 크게 출렁이는 품목을 빼고 계산한 물가상승률이에요. 일시적인 충격을 걷어내 물가가 기조적으로 어느 방향으로 가는지 보여줘요. 다만 장바구니 물가가 빠져 있어 사람들이 느끼는 체감물가와는 차이가 날 수 있어요."}, {"id": 100, "word": "글래스-스티걸법", "beforeLength": 986, "after": "1933년 미국이 상업은행과 투자은행의 업무를 엄격히 나누려고 만든 은행법이에요. 예금을 받는 상업은행은 증권 발행이나 인수를 할 수 없게 하는 방식으로 두 업무를 갈라놓았어요. 대공황 때 은행의 무분별한 투자가 위기를 키웠다는 반성에서 나왔고, 1999년에 핵심 조항이 폐지됐어요."}, {"id": 102, "word": "글로벌 금융위기", "beforeLength": 641, "after": "2008년 미국에서 시작되어 전 세계 금융시스템과 경제를 뒤흔든 위기예요. 신용이 낮은 사람에게 내준 주택대출이 집값 하락으로 부실해지자, 이를 묶어 만든 증권의 가치가 폭락했어요. 위기 뒤 각국은 은행 자본 규제를 강화하고 금융시스템 전체를 감시하는 정책을 도입했어요."}, {"id": 103, "word": "글로벌금융안전망", "beforeLength": 616, "after": "외화가 갑자기 부족해진 나라가 달러 같은 외화를 구할 수 있도록 마련된 국제적 안전장치 전체를 말해요. 각국의 외환보유액, 중앙은행 간 통화스왑, 지역 간 협정, 국제통화기금 지원이 여러 겹으로 쌓인 구조예요. 위기의 크기와 성격에 맞게 층별로 대응하려고 이렇게 만들었어요."}, {"id": 104, "word": "금리선물", "beforeLength": 968, "after": "미래의 정해진 날 금리 상품을 지금 정한 가격으로 사고팔기로 약속하는 계약이에요. 대표 상품인 국채선물은 가상의 국채를 기초자산으로 삼아 가격으로 거래돼요. 금리가 오를 것 같으면 미리 팔아 두는 식으로 금리 변동 위험을 줄이는 데 써요."}, {"id": 105, "word": "금리스왑", "beforeLength": 942, "after": "두 거래 당사자가 원금은 그대로 두고 고정금리 이자와 변동금리 이자를 서로 바꿔 내는 거래예요. 예를 들어 변동금리로 돈을 빌린 회사는 이 거래로 사실상 고정금리 이자만 내는 효과를 얻을 수 있어요. 금리 변동 위험을 줄이거나 차입 비용을 아끼려는 금융기관과 기업이 많이 써요."}, {"id": 106, "word": "금리자유화", "beforeLength": 712, "after": "정부가 정하던 금리 규제를 없애 금리가 시장의 자금 수요와 공급에 따라 정해지게 하는 조치예요. 예전에는 금융안정을 이유로 예금·대출 금리 상한을 두는 나라가 많았어요. 물가가 높던 1970~80년대 규제가 오히려 은행 자금 중개를 위축시키자 각국이 단계적으로 풀었어요."}, {"id": 107, "word": "금리평가이론", "beforeLength": 600, "after": "자본이 자유롭게 오가는 시장에서는 두 나라의 금리 차이만큼 현물환율과 선물환율의 차이가 생긴다는 이론이에요. 같은 돈을 한국 채권에 넣든 미국 채권에 넣고 환율을 미리 고정하든 결과가 같아야 한다는 생각에서 나왔어요. 차이가 나면 차익거래가 일어나 결국 균형으로 돌아간다고 봐요."}, {"id": 108, "word": "금본위제", "beforeLength": 589, "after": "나라의 통화 가치를 일정량의 금에 고정하고 지폐를 금과 바꿔 주던 화폐 제도예요. 각 통화가 금을 기준으로 값이 정해지니 통화끼리의 교환 비율도 자연히 고정됐어요. 1800년대 영국을 시작으로 널리 퍼졌지만, 금 보유량에 묶여 통화를 유연하게 늘리기 어렵다는 한계로 사라졌어요."}, {"id": 109, "word": "금산분리", "beforeLength": 356, "after": "산업자본과 금융자본이 지나치게 결합하지 못하도록 막는 원칙이에요. 대기업이 은행을 가지면 은행 돈을 자기 회사를 위한 사금고처럼 쓸 위험이 있어요. 그래서 우리나라는 은행법으로 산업자본이 가질 수 있는 은행 지분을 원칙적으로 4%로 제한해요."}, {"id": 110, "word": "금융 하부구조", "beforeLength": 287, "after": "지급결제시스템, 신용평가제도, 증권거래소처럼 금융거래가 원활히 이뤄지도록 받쳐 주는 제도와 기관을 말해요. 도로나 항만이 생산에 직접 쓰이지 않아도 꼭 필요한 것처럼 금융의 기반 역할을 해요. 잘 갖춰지면 거래가 투명해지고 비용과 위험이 줄어 금융이 더 효율적으로 돌아가요."}, {"id": 111, "word": "금융공황", "beforeLength": 569, "after": "한 은행에서 시작된 예금 인출 사태가 다른 금융기관으로 번져 금융시장 전체의 돈줄이 막히는 현상이에요. 사람들이 불안해 한꺼번에 돈을 찾으면 멀쩡한 은행도 버티기 어려워지고 대출이 급격히 줄어요. 1907년 미국 사례처럼 많은 은행과 기업이 파산하고 경기침체가 깊어질 수 있어요."}, {"id": 112, "word": "금융불안지수(FSI)", "beforeLength": 438, "after": "금융시장이 얼마나 불안한지 빠르게 파악하려고 만든 조기경보용 지수예요. 한국은행은 주가 변동성, 환율 변동성, 연체율 같은 여러 지표를 묶어 매달 계산해요. 0에서 100 사이 값으로 나타내며 일정 수준을 넘으면 주의나 위험 단계로 판단해요."}, {"id": 113, "word": "금융사이클", "beforeLength": 368, "after": "대출 같은 신용과 집값·주가 같은 자산가격이 함께 부풀었다가 꺼지기를 되풀이하는 금융의 흐름이에요. 자산값이 오르면 담보 가치가 커져 대출이 늘고, 늘어난 대출이 다시 자산값을 밀어 올리는 식으로 움직여요. 보통 경기순환보다 주기가 길어 금융위기 위험을 가늠할 때 함께 살펴봐요."}, {"id": 114, "word": "금융상황지수(FCI)", "beforeLength": 509, "after": "금리, 환율, 주가, 집값 같은 금융 변수를 하나로 묶어 금융 여건이 느슨한지 빡빡한지 보여주는 지수예요. 금리가 내리고 주가가 오르면 돈을 구하기 쉬운 완화 상태로, 반대면 긴축 상태로 읽어요. 통화정책의 효과가 시장에 어떻게 전달되는지 확인하려고 중앙은행들이 참고해요."}, {"id": 115, "word": "금융시스템 상호연계성", "beforeLength": 251, "after": "금융회사들이 서로 돈을 빌리고 빌려주는 거래로 얼마나 촘촘히 얽혀 있는지를 나타내는 개념이에요. 실제 거래 규모나 금융회사 주가·금리가 함께 움직이는 정도를 보고 연결 구조를 분석해요. 연결이 강할수록 한 곳의 부실이 다른 곳으로 빠르게 번질 수 있어 위기 감시의 핵심이 돼요."}, {"id": 116, "word": "금융시장인프라", "beforeLength": 545, "after": "금융거래의 지급, 청산, 결제, 기록을 처리하는 시스템과 기관을 통틀어 부르는 말이에요. 자금이체 시스템, 증권결제시스템, 증권을 맡아 관리하는 예탁기관, 결제를 보장하는 중앙청산소 등이 있어요. 여기에 문제가 생기면 금융 전체가 멈출 수 있어 중앙은행과 당국이 꼼꼼히 감시해요."}, {"id": 117, "word": "금융안정", "beforeLength": 734, "after": "금융회사가 제 역할을 하고 시장의 신뢰가 유지되며 결제 같은 인프라가 잘 돌아가는 상태를 말해요. 한 금융회사나 시장의 불안이 전체 시스템으로 번지지 않아야 이 상태가 유지돼요. 물가안정, 경제성장과 함께 정책당국이 반드시 지켜야 할 목표로 꼽혀요."}, {"id": 118, "word": "금융안정위원회(FSB)", "beforeLength": 414, "after": "주요국 중앙은행, 재무부, 감독기관이 모여 국제 금융시스템의 안정을 논의하는 기구예요. 2009년 기존 금융안정포럼을 확대 개편해 만들었으며, 금융 규제 기준을 조율하고 취약점을 점검해요. 우리나라에서는 한국은행과 금융위원회가 참여하고 있어요."}, {"id": 119, "word": "금융연관비율(골드스미스비율)", "beforeLength": 345, "after": "한 나라의 금융자산이 건물·설비 같은 실물자산의 몇 배인지 나타내는 비율이에요. 실물자산 규모를 구하기 어려우면 명목 국민총소득으로 대신 나누기도 해요. 금융이 얼마나 발달했는지를 보여주며 보통 경제가 성장할수록 높아져요."}, {"id": 120, "word": "금융의 증권화", "beforeLength": 472, "after": "대출채권처럼 쉽게 팔기 어려운 자산을 사고팔 수 있는 증권으로 바꾸는 것을 말해요. 여러 대출을 한데 묶어 원래 주인과 분리한 뒤, 그 대출에서 나오는 원리금을 바탕으로 증권을 발행해요. 주택담보대출을 묶은 주택저당증권이 대표적이며, 금융기관은 이렇게 해서 자금을 빨리 회수해요."}, {"id": 121, "word": "금융의 탈중개화", "beforeLength": 295, "after": "은행 같은 중개기관을 거치지 않고 돈이 필요한 사람과 가진 사람이 직접 거래하는 현상이에요. 개인끼리 돈을 빌려주는 P2P대출이나 블록체인을 이용한 송금이 대표적인 예예요. 핀테크가 발달할수록 기존 금융회사의 역할은 줄고 서비스 공급자는 다양해져요."}, {"id": 122, "word": "금융의 탈집중화", "beforeLength": 426, "after": "핀테크 기업이 들어오면서 한 금융회사가 묶어 팔던 서비스가 분야별로 잘게 나뉘는 현상이에요. 예를 들어 지점 없는 인터넷전문은행이 대출 고객을 끌어오고, 해외송금은 수수료가 싼 핀테크 업체가 맡아요. 중개기관을 아예 건너뛰는 탈중개화와 비슷하지만 서비스의 분화에 초점을 둬요."}, {"id": 123, "word": "금융이해력", "beforeLength": 579, "after": "돈을 잘 관리하고 합리적인 금융 결정을 내리는 데 필요한 지식과 행동, 태도를 아우르는 능력이에요. 금융상품을 이해하는 지식, 예산 관리와 저축 같은 실제 행동, 미래를 계획하는 태도로 나눠 평가해요. 이 능력이 높을수록 과도한 빚이나 금융사기를 피하고 노후를 준비하기 쉬워요."}, {"id": 124, "word": "금융제도", "beforeLength": 521, "after": "금융거래가 이뤄지는 틀과 규칙 전체를 가리키는 말이에요. 돈이 오가는 금융시장, 거래를 이어주는 금융기관, 결제 시스템 같은 금융 하부구조로 나눠 볼 수 있어요. 이 세 요소가 잘 맞물려야 돈이 필요한 곳으로 효율적으로 흘러가요."}, {"id": 125, "word": "금융중개지원대출제도", "beforeLength": 664, "after": "은행이 중소기업 대출을 늘리도록 한국은행이 대출 실적에 맞춰 싼 금리로 자금을 대주는 제도예요. 은행이 먼저 자기 돈으로 요건에 맞는 중소기업에 대출하면, 한국은행이 나중에 실적에 비례해 자금을 지원해요. 금리가 보통 기준금리보다 낮아 은행이 중소기업 대출을 늘릴 유인이 생겨요."}]$payload$::jsonb) AS r(id integer, word text, "beforeLength" integer, after text))
SELECT count(*) FILTER (WHERE w.detailed_meaning = r.after) AS applied_rows,
       count(b.id) AS backed_up_rows,
       120 AS expected
FROM r JOIN public.words w ON w.id = r.id
LEFT JOIN public.words_detailed_meaning_backup_v1 b ON b.id = r.id;
